import unittest

from discount import discount


class TestDiscount(unittest.TestCase):
    def test_a_big_order_gets_ten_off(self):
        self.assertEqual(discount(150), 10)

    def test_a_small_order_gets_nothing(self):
        self.assertEqual(discount(50), 0)
